const { execSync } = require('child_process');
const fs = require('fs');

const objects = execSync('git rev-list --objects --all', { encoding: 'utf8', maxBuffer: 10 * 1024 * 1024 })
  .trim()
  .split('\n');

console.log(`Checking ${objects.length} objects from rev-list --all...`);

let found = 0;
for (const line of objects) {
  const [hash, ...pathParts] = line.trim().split(/\s+/);
  const p = pathParts.join(' ');
  try {
    const type = execSync(`git cat-file -t ${hash}`, { encoding: 'utf8' }).trim();
    if (type === 'blob') {
      const content = execSync(`git cat-file -p ${hash}`, { encoding: 'utf8', maxBuffer: 10 * 1024 * 1024 });
      if (content.includes('--mc-radius-2xs') || content.includes('History at the production floor (T140)')) {
        console.log(`FOUND in ${hash} (${p || 'no-path'}): length=${content.length}`);
        found++;
      }
    }
  } catch (e) {}
}

console.log(`Total found in rev-list --all: ${found}`);

// Now let's check dangling / unreachable blobs
try {
  const unreachable = execSync('git fsck --unreachable --no-reflogs', { encoding: 'utf8' })
    .trim()
    .split('\n');
  console.log(`Checking ${unreachable.length} unreachable objects...`);
  for (const line of unreachable) {
    const match = line.match(/unreachable (blob|tree|commit) ([0-9a-f]{40})/);
    if (match) {
      const [, type, hash] = match;
      if (type === 'blob') {
        const content = execSync(`git cat-file -p ${hash}`, { encoding: 'utf8', maxBuffer: 10 * 1024 * 1024 });
        if (content.includes('--mc-radius-2xs') || content.includes('History at the production floor (T140)') || content.includes('container: terminal-pane')) {
          console.log(`FOUND in unreachable ${hash}: length=${content.length}`);
          fs.writeFileSync(`found_blob_${hash}.txt`, content);
        }
      }
    }
  }
} catch (e) {
  console.log('Error checking unreachable:', e.message);
}
